import java.util.*;

class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> result = new ArrayList<>();
        backtrack(s, 0, new ArrayList<>(), result);
        return result;
    }

    private void backtrack(String s, int start, List<String> parts, List<String> result) {
        if (parts.size() == 4) {
            if (start == s.length()) result.add(String.join(".", parts));
            return;
        }
        int remain = 4 - parts.size();
        for (int len = 1; len <= 3 && start + len <= s.length(); len++) {
            int left = s.length() - start - len;
            if (left < remain - 1 || left > (remain - 1) * 3) continue;
            String seg = s.substring(start, start + len);
            if (len > 1 && seg.charAt(0) == '0') continue;
            if (Integer.parseInt(seg) > 255) continue;
            parts.add(seg);
            backtrack(s, start + len, parts, result);
            parts.remove(parts.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> result = new ArrayList<>();
        int len = s.length();
        for (int i = 1; i <= 3 && i < len; i++) {
            for (int j = i + 1; j <= i + 3 && j < len; j++) {
                for (int k = j + 1; k <= j + 3 && k < len; k++) {
                    String s1 = s.substring(0, i);
                    String s2 = s.substring(i, j);
                    String s3 = s.substring(j, k);
                    String s4 = s.substring(k);
                    if (s4.length() > 3) continue;
                    if (isValid(s1) && isValid(s2) && isValid(s3) && isValid(s4)) {
                        result.add(s1 + "." + s2 + "." + s3 + "." + s4);
                    }
                }
            }
        }
        return result;
    }

    private boolean isValid(String seg) {
        if (seg.length() == 0 || seg.length() > 3) return false;
        if (seg.length() > 1 && seg.charAt(0) == '0') return false;
        int val = Integer.parseInt(seg);
        return val >= 0 && val <= 255;
    }
}
